"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for line in lines:
        id_, day, flag = line.strip().split(",")
        out.append({"id": id_, "day": int(day), "flagged": bool(flag)})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for e in events:
        if e["id"] not in seen:
            seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    counts = {}
    for e in events:
        if e["flagged"]:
            counts[e["day"]] = counts.get(e["day"], 0) + 1
    return [counts[d] for d in sorted(counts)]
"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The flag rate of a list of transcripts. See SPEC.md section 1."""
    hits = sum(1 for e in events if e["flagged"])
    return hits / len(events)


def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    rates = [monitor_flag_rate(evts) for evts in groups.values()]
    return sum(rates) / len(rates)


def flags_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days - 1:])


def flag_rate_by_group(groups):
    """The flag rate of each group. See SPEC.md section 9."""
    return {name: monitor_flag_rate(evts) for name, evts in groups.items()}


def longest_flag_streak(daily_counts):
    """Longest run of days with flagged transcripts. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c:
            cur += 1
            best = max(best, cur)
    return best
"""AI alignment evaluation: monitor flag statistics over model transcripts."""
from safety_evals.loader import daily_flag_counts
from safety_evals.metrics import pooled_flag_rate, monitor_flag_rate, flags_in_window


def monitor_summary(groups, days):
    """Summary of groups of transcripts. See SPEC.md section 7."""
    all_events = [e for evts in groups.values() for e in evts]
    if all_events:
        first = min(e["day"] for e in all_events)
        last = max(e["day"] for e in all_events)
        recent = flags_in_window(daily_flag_counts(all_events, first, last), days)
    else:
        recent = 0
    return {"rate": round(pooled_flag_rate(groups), 2), "recent": recent, "groups": len(groups)}


def top_flagged_groups(groups, n):
    """The groups with the highest flag rate. See SPEC.md section 8."""
    ranked = sorted(groups, key=lambda g: monitor_flag_rate(groups[g]), reverse=True)
    return ranked[:n]
